<script setup lang="ts">
const config = useRuntimeConfig()
const api = config.public.apiBase
const { data: stats, refresh } = await useFetch<any>(`${api}/api/dashboard`, { default: () => ({ campaigns: 0, content_drafts: 0, confirmed_commission: 0, currency: 'USD' }) })
const { data: campaigns, refresh: refreshCampaigns } = await useFetch<any[]>(`${api}/api/campaigns`, { default: () => [] })
const { data: opportunities, refresh: refreshOpportunities } = await useFetch<any[]>(`${api}/api/research/opportunities`, { default: () => [] })
const { data: networks } = await useFetch<any[]>(`${api}/api/research/networks`, { default: () => [] })
const productName = ref(''), vendor = ref(''), commission = ref(20), recurring = ref(false), evidence = ref(3)
const systemeAffiliateLink = 'https://systeme.io/fr?sa=sa028522389209c1b0fb00f4f72d0250aa9dca6f5f'
const draftBusy = ref(false), draftMessage = ref('')
const imageAgentBusy = ref(false), imageAgentMessage = ref('')
const collaborationTopic = ref('Lên ý tưởng bài viết affiliate hôm nay')
const collaborationBusy = ref(false), collaborationError = ref(''), collaborationMessages = ref<any[]>([]), collaborationSession = ref('')
async function loadAgentConversation() { try { collaborationMessages.value = await $fetch<any[]>(`${api}/api/agents/conversations?limit=40`) } catch {} }
async function startAgentDiscussion() {
  collaborationBusy.value = true; collaborationError.value = ''
  autopilotBusy.value = true; autopilotMessage.value = ''
  try {
    if (!selectedCampaignId.value) {
      await $fetch(`${api}/api/setup/saas-starter`, { method:'POST' })
      await refreshCampaigns()
    }
    const meeting:any = await $fetch(`${api}/api/agents/collaborate`, { method:'POST', body:{ topic:collaborationTopic.value, campaign_id:selectedCampaignId.value || null, rounds:2 } })
    collaborationSession.value = meeting.session_id
    collaborationMessages.value = (meeting.messages || []).map((m:any,i:number)=>({...m,id:i,session_id:meeting.session_id}))
    const approvedBrief = (meeting.messages || []).map((m:any)=>`${m.agent}: ${m.message}`).join("\n\n").slice(0,9500)
    const imageBrief = [...(meeting.messages || [])].reverse().find((m:any)=>m.agent === 'Trợ lý hình ảnh')?.message || ''
    const result:any = await $fetch(`${api}/api/autopilot/run`, { method:'POST', body:{ topic:collaborationTopic.value, agent_brief:approvedBrief } })
    const imageErrors:string[] = []
    let imagesCreated = 0
    if (autoGenerateImages.value) {
      for (const d of (result.drafts || [])) {
        try {
          await $fetch(`${api}/api/media/generate`, { method:'POST', body:{
            draft_id:d.id,
            prompt:`Create a premium, photorealistic editorial campaign image for this affiliate post. Follow this visual direction agreed by the Trợ lý hình ảnh: ${imageBrief.slice(0,650)}. Title: ${d.title}. Context: ${String(d.body || '').slice(0,500)}. Audience: small business owners, creators and online entrepreneurs. Square 1:1 composition. No text, logos or watermarks.`
          }})
          imagesCreated++
        } catch (e:any) { imageErrors.push(`#${d.id}`) }
      }
    }
    autopilotMessage.value = `Trợ lý nội dung đã tạo ${result.created} bản nháp. ${autoGenerateImages.value ? `Trợ lý hình ảnh đã tạo ${imagesCreated}/${(result.drafts || []).length} ảnh.` : 'Đã bỏ qua tạo ảnh theo cài đặt.'} Tất cả được lưu để bạn duyệt; không tự đăng.`
    if (imageErrors.length) autopilotMessage.value += ` Lỗi tạo ảnh ở bản nháp ${imageErrors.join(', ')}; có thể thử tạo lại trong từng bản nháp.`
    await Promise.all([refresh(),loadDrafts(),loadMedia(),loadActivity()])
  } catch(e:any) {
    collaborationError.value = e?.data?.detail || 'Quy trình hai Agent chưa hoàn tất. Kiểm tra OpenAI và Cloudinary.'
  } finally { collaborationBusy.value=false; autopilotBusy.value=false }
}
async function runImageAgent() {
  const draft = selectedDraft.value || drafts.value[0]
  if (!draft) { imageAgentMessage.value = 'Hãy tạo hoặc chọn một bản nháp trước khi yêu cầu Trợ lý hình ảnh.'; return }
  imageAgentBusy.value = true; imageAgentMessage.value = ''
  try {
    await generateDraftImage(draft)
    imageAgentMessage.value = mediaMessage.value || 'Trợ lý hình ảnh đã tạo ảnh cho bản nháp.'
    await Promise.all([loadDrafts(), loadMedia(), loadActivity()])
  } catch (e:any) {
    imageAgentMessage.value = e?.data?.detail || 'Trợ lý hình ảnh chưa thể tạo ảnh. Kiểm tra OpenAI và Cloudinary.'
  } finally { imageAgentBusy.value = false }
}
const autopilotBusy = ref(false), autopilotMessage = ref('')
const drafts = ref<any[]>([])
const selectedDraftId = ref<number | null>(null), selectedMediaId = ref<number | null>(null), draftImageMessage = ref('')
const selectedDraft = computed(() => drafts.value.find((d:any) => d.id === selectedDraftId.value) || null)
const selectedMedia = computed(() => media.value.find((m:any) => m.id === selectedMediaId.value) || null)
const draftSearch = ref(''), draftStatusFilter = ref('all')
const filteredDrafts = computed(() => drafts.value.filter((d:any) => d.status !== 'published' && (draftStatusFilter.value === 'all' || d.status === draftStatusFilter.value) && `${d.title || ''} ${d.body || ''}`.toLowerCase().includes(draftSearch.value.toLowerCase().trim())))
const activity = ref<any[]>([]), media = ref<any[]>([]), mediaBusy = ref(false), mediaMessage = ref('')
const imageBusy = ref<number | null>(null), autoGenerateImages = ref(false), activityDate = ref('')
const publishStatus = ref<any>({ connected: false, facebook_connected: false, auto_publish: false, schedule_time: '19:30', timezone: 'Asia/Ho_Chi_Minh' }), publishBusy = ref<number | null>(null)
const publishNetworks = ref(['facebook','threads'])
const publishDate = ref(new Date(Date.now() + 86400000).toISOString().slice(0,16))
async function loadPublishing() { publishStatus.value = await $fetch<any>(`${api}/api/publishing/status`) }
async function toggleAutoPublish() { const requested = !publishStatus.value.auto_publish; publishStatus.value.auto_publish = requested; try { const saved:any = await $fetch<any>(`${api}/api/publishing/settings`, { method:'PUT', body:{auto_publish:requested} }); publishStatus.value.auto_publish = saved.auto_publish; await loadActivity() } catch(e:any) { publishStatus.value.auto_publish = !requested; autopilotMessage.value = e?.data?.detail || 'Không thể cập nhật lịch tự đăng.' } }
async function scheduleDraft(d:any) { if (!publishNetworks.value.length) { autopilotMessage.value='Hãy chọn ít nhất một nền tảng.'; return }; publishBusy.value=d.id; try { const result:any = await $fetch(`${api}/api/drafts/${d.id}/publish`, {method:'POST',body:{date_time:new Date().toISOString().slice(0,16),networks:publishNetworks.value}}); if (result.published?.length) d.status='published'; const ok=(result.published || []).map((x:any)=>x.platform); const failed=(result.failures || []).map((x:any)=>`${x.platform}: ${x.error}`); autopilotMessage.value = failed.length ? `Đã đăng: ${ok.join(', ') || 'không có'}. Thất bại: ${failed.join(' | ')}` : `Đã đăng bài viết #${d.id} lên: ${ok.join(', ')}.`; await Promise.all([loadActivity(),loadDrafts()]) } catch(e:any) { autopilotMessage.value=e?.data?.detail || 'Không thể đăng bài viết.' } finally { publishBusy.value=null } }
async function attachSelectedImage(d:any) { if (!selectedMedia.value) return; draftImageMessage.value=''; try { const result:any=await $fetch(`${api}/api/drafts/${d.id}/image?asset_id=${selectedMedia.value.id}`,{method:'PUT'}); d.image_url=result.image_url; draftImageMessage.value=`Đã gắn ảnh ${selectedMedia.value.filename || selectedMedia.value.public_id} vào bài viết #${d.id}.`; await loadDrafts() } catch(e:any) { draftImageMessage.value=e?.data?.detail || 'Không thể gắn ảnh vào bài viết viết.' } }
async function loadActivity() { const q = activityDate.value ? `&date_from=${activityDate.value}&date_to=${activityDate.value}` : ''; activity.value = await $fetch<any[]>(`${api}/api/activity?limit=100${q}`) }
async function generateDraftImage(d: any) { imageBusy.value = d.id; mediaMessage.value = ''; try { const result: any = await $fetch(`${api}/api/media/generate`, { method: 'POST', body: { draft_id: d.id, prompt: `Create an image that visually communicates this social post. Topic: ${d.title}. Context: ${String(d.body || '').slice(0, 700)}. Audience: small business owners, creators and online entrepreneurs. Square 1:1 composition.` } }); d.image_url = result.url; mediaMessage.value = 'Đã tạo ảnh AI và lưu lên Cloudinary.'; await Promise.all([loadMedia(), loadActivity()]); } catch (e: any) { mediaMessage.value = e?.data?.detail || 'Không thể tạo ảnh bằng AI.'; } finally { imageBusy.value = null } }
async function loadMedia() { media.value = await $fetch<any[]>(`${api}/api/media?limit=100`) }
async function uploadMedia(event: Event) { const input = event.target as HTMLInputElement; const file = input.files?.[0]; if (!file) return; mediaBusy.value = true; mediaMessage.value = ''; try { const body = new FormData(); body.append('file', file); await $fetch(`${api}/api/media/upload`, { method: 'POST', body }); mediaMessage.value = 'Đã tải ảnh lên Cloudinary.'; await Promise.all([loadMedia(), loadActivity()]); } catch (e: any) { mediaMessage.value = e?.data?.detail || 'Tải ảnh thất bại.' } finally { mediaBusy.value = false; input.value = '' } }
const selectedCampaignId = computed(() => campaigns.value.find((c: any) => c.name === 'SaaS Tools for Small Businesses')?.id)
await Promise.all([loadActivity(), loadMedia(), loadPublishing(), loadAgentConversation(), loadDrafts()]).catch(() => {})
async function loadDrafts() {
  if (!selectedCampaignId.value) { drafts.value = []; return }
  drafts.value = await $fetch<any[]>(`${api}/api/campaigns/${selectedCampaignId.value}/drafts`)
}
async function runAutopilot() {
  autopilotBusy.value = true; autopilotMessage.value = ''
  try {
    const result: any = await $fetch(api + '/api/autopilot/run', { method: 'POST' })
    autopilotMessage.value = `Created ${result.created} drafts; skipped ${result.skipped} duplicates. ${result.drafts_total} total drafts in campaign.`
    if (autoGenerateImages.value && result.drafts?.length) { for (const d of result.drafts) { try { await $fetch(`${api}/api/media/generate`, { method: 'POST', body: { draft_id: d.id, prompt: `Square editorial image for a helpful social post titled: ${d.title}. Audience: small business owners and creators. No text or logos.` } }); } catch (e: any) { autopilotMessage.value += ` Image generation failed for draft #${d.id}.`; } } }
    await Promise.all([refresh(), loadDrafts(), loadActivity(), loadMedia()])
  } catch (e: any) { autopilotMessage.value = e?.data?.detail || 'Không thể chạy trợ lý nội dung. Hãy kiểm tra cấu hình AI và nhật ký máy chủ.' }
  finally { autopilotBusy.value = false }
}
async function createSystemeDraft() {
  const campaign = campaigns.value.find((c: any) => c.name === 'SaaS Tools for Small Businesses')
  if (!campaign) { draftMessage.value = 'Trước tiên hãy tải danh sách SaaS mẫu.'; return }
  draftBusy.value = true; draftMessage.value = ''
  const title = 'systeme.io review: an all-in-one toolkit for small businesses'
  const body = `Looking for a simpler way to build a website funnel, collect leads and send marketing emails?

systeme.io brings several online-business tools together, including sales funnels, email marketing, websites and online courses. It may be worth comparing if you are a solo founder, creator or small business trying to reduce the number of separate tools you manage.

Before choosing, check the current plan limits, integrations, support options and pricing against your needs. Start with the free plan if it fits your use case, and upgrade only when you need the additional features.

Explore systeme.io here: ${systemeAffiliateLink}

Disclosure: This is an affiliate link. If you sign up or buy through it, I may earn a commission at no extra cost to you. Please review the provider's current terms before purchasing.`
  try {
    await $fetch(`${api}/api/campaigns/${campaign.id}/drafts`, { method: 'POST', body: { title, body } })
    draftMessage.value = 'Đã tạo bản nháp đầu tiên. Hãy kiểm duyệt trước khi đăng.'
    await refresh()
  } catch (e: any) { draftMessage.value = e?.data?.detail || 'Không thể tạo bản nháp.' }
  finally { draftBusy.value = false }
}
const seedBusy = ref(false), seedMessage = ref('')
async function loadSaaSStarter() {
  seedBusy.value = true; seedMessage.value = ''
  try {
    const result: any = await $fetch(api + '/api/setup/saas-starter', { method: 'POST' })
    seedMessage.value = 'Added ' + result.opportunities_added + ' new candidates. ' + result.opportunities_total + ' total in the shortlist.'
    await Promise.all([refreshOpportunities(), refresh(), refreshCampaigns()])
  } catch (e: any) { seedMessage.value = e?.data?.detail || 'Không thể tải danh sách SaaS.' }
  finally { seedBusy.value = false }
}
const researchBusy = ref(false), researchError = ref('')
async function addOpportunity() {
  if (productName.value.trim().length < 2) return
  researchBusy.value = true; researchError.value = ''
  try {
    await $fetch(`${api}/api/research/opportunities`, { method: 'POST', body: { product_name: productName.value, vendor_name: vendor.value, category: 'software', network: 'PartnerStack / direct', target_regions: 'US,UK,EU', commission_pct: commission.value, recurring: recurring.value, evidence_quality: evidence.value, audience_fit: 4, differentiation: 'Solves a specific recurring workflow problem for small businesses and creators.' } })
    productName.value = ''; vendor.value = ''; await refreshOpportunities()
  } catch (e: any) { researchError.value = e?.data?.detail || 'Không thể lưu cơ hội tiếp thị' }
  finally { researchBusy.value = false }
}
async function analyzeOpportunity(id: number) { await $fetch(`${api}/api/research/opportunities/${id}/analyze`, { method: 'POST' }); await refreshOpportunities() }
const name = ref(''), niche = ref('technology'), busy = ref(false), error = ref('')
async function createCampaign() {
  if (name.value.trim().length < 2) return
  busy.value = true; error.value = ''
  try {
    await $fetch(`${api}/api/campaigns`, { method: 'POST', body: { name: name.value, niche: niche.value, network: 'unselected' } })
    name.value = ''; await Promise.all([refresh(), refreshCampaigns()])
  } catch (e: any) { error.value = e?.data?.detail || 'Không thể tạo chiến dịch' }
  finally { busy.value = false }
}
</script>
<template>
  <main class="shell">
    <header><div><p class="eyebrow">AFFPILOT · DOANH NGHIỆP TỰ ĐỘNG</p><h1>Văn phòng AffPilot</h1><p class="muted">Văn phòng vận hành Affiliate bằng AI · Nghiên cứu → Sáng tạo → Xuất bản → Tăng trưởng</p></div><span class="live">● HỆ THỐNG ĐANG HOẠT ĐỘNG</span></header>
    <section class="metrics"><article><small>CHIẾN DỊCH</small><strong>{{ stats.campaigns }}</strong></article><article><small>BẢN NHÁP NỘI DUNG</small><strong>{{ stats.content_drafts }}</strong></article><article><small>HOA HỒNG ĐÃ XÁC NHẬN</small><strong>${{ Number(stats.confirmed_commission || 0).toFixed(2) }}</strong><em>Chỉ tính chuyển đổi đã xác nhận</em></article></section>

    <section class="office-floor">
      <div class="floor-heading"><div><p class="eyebrow">TRỤ SỞ ẢO</p><h2>Không gian làm việc AI</h2><p class="muted">Chọn từng phòng ban để theo dõi công việc và điều phối các trợ lý AI.</p></div><span class="office-live">● 2 TRỢ LÝ AI · SẴN SÀNG</span></div>
      <div class="room-grid">
        <article class="room-card room-command"><div class="room-scene"><span class="room-icon">🏢</span><span class="room-orb"></span><div class="room-desk"></div></div><div class="room-copy"><small>01 · ĐIỀU HÀNH</small><h3>Phòng điều hành</h3><p>Trung tâm quản lý chiến dịch và hiệu quả kinh doanh.</p><b>{{ campaigns.length }} chiến dịch · {{ stats.content_drafts }} nội dung</b></div></article>
        <article class="room-card room-creative"><div class="room-scene"><span class="room-icon">🎨</span><span class="room-orb"></span><div class="room-desk"></div></div><div class="room-copy"><small>02 · PHÒNG SÁNG TẠO</small><h3>Phòng sáng tạo</h3><p>Nơi hai trợ lý AI phối hợp tạo hình ảnh và nội dung.</p><b>Trợ lý hình ảnh · Trợ lý nội dung</b></div></article>
        <article class="room-card room-publish"><div class="room-scene"><span class="room-icon">📡</span><span class="room-orb"></span><div class="room-desk"></div></div><div class="room-copy"><small>03 · XUẤT BẢN</small><h3>Phòng xuất bản</h3><p>Kiểm duyệt bản nháp và đăng thủ công lên các nền tảng.</p><b>Duyệt thủ công · Facebook / Threads</b></div></article>
        <article class="room-card room-data"><div class="room-scene"><span class="room-icon">🗄️</span><span class="room-orb"></span><div class="room-desk"></div></div><div class="room-copy"><small>04 · DỮ LIỆU & TÀI NGUYÊN</small><h3>Phòng dữ liệu</h3><p>Thư viện ảnh, nội dung và lịch sử hoạt động.</p><b>{{ media.length }} ảnh · {{ activity.length }} hoạt động gần đây</b></div></article>
      </div>
      <div class="agents-heading"><div><p class="eyebrow">ĐỘI NGŨ AI</p><h2>Nhân sự AI của AffPilot</h2></div><span class="muted">Điều khiển riêng từng trợ lý AI</span></div>

      <div class="collab-panel"><div class="collab-head"><div><small>PHỐI HỢP TRỢ LÝ AI · PHÒNG LÀM VIỆC TRỰC TIẾP</small><h3>Cuộc họp giữa hai AI Agent</h3><p>Hai Agent trao đổi, phản biện brief; sau đó Trợ lý nội dung tạo 3 bản nháp và Trợ lý hình ảnh tạo ảnh cho từng bài viết.</p></div><span class="collab-pulse">{{ collaborationBusy ? "● CÁC TRỢ LÝ ĐANG LÀM VIỆC" : "● ĐỘI NGŨ AI" }}</span></div><div class="collab-controls"><input v-model="collaborationTopic" placeholder="Nhập chủ đề để hai trợ lý cùng thảo luận..." /><button :disabled="collaborationBusy" @click="startAgentDiscussion">{{ collaborationBusy ? 'Đang thảo luận và tạo nội dung…' : '▶ Bắt đầu thảo luận và sản xuất' }}</button></div><p v-if="collaborationError" class="agent-message">{{ collaborationError }}</p><div v-if="collaborationMessages.length" class="conversation-feed"><article v-for="(m,i) in collaborationMessages" :key="m.id || i" :class="['conversation-message',m.agent === 'Trợ lý hình ảnh' ? 'from-image' : 'from-content']"><div class="conversation-avatar">{{ m.agent === 'Trợ lý hình ảnh' ? '🎨' : '✍️' }}</div><div><b>{{ m.agent }}</b><p>{{ m.message }}</p></div></article></div><p v-else class="conversation-empty">Chưa có cuộc họp nào. Nhập chủ đề rồi bấm bắt đầu để hai trợ lý phối hợp.</p></div>
      <div class="agent-grid">
        <article class="agent-card image-agent"><div class="agent-avatar">✦</div><div class="agent-info"><small>TRỢ LÝ 01 · SẢN XUẤT HÌNH ẢNH</small><h3>Trợ lý hình ảnh <span class="agent-status">{{ imageAgentBusy || collaborationBusy ? "● Đang xử lý" : "● Sẵn sàng" }}</span></h3><p>Thiết kế hình ảnh quảng bá theo chủ đề bài viết viết, lưu vào Cloudinary và gắn vào bản nháp phù hợp.</p><div class="agent-meta"><span>Cloudflare Workers AI</span><span>Cloudinary</span><span>Hằng ngày · 18:30</span></div><button :disabled="imageAgentBusy || collaborationBusy" @click="runImageAgent">{{ imageAgentBusy ? 'Đang tạo hình ảnh…' : '▶ Chạy Trợ lý hình ảnh' }}</button><p v-if="imageAgentMessage" class="agent-message">{{ imageAgentMessage }}</p></div></article>
        <article class="agent-card content-agent"><div class="agent-avatar">✎</div><div class="agent-info"><small>TRỢ LÝ 02 · CHIẾN LƯỢC NỘI DUNG</small><h3>Trợ lý nội dung <span class="agent-status">{{ autopilotBusy || collaborationBusy ? "● Đang xử lý" : "● Sẵn sàng" }}</span></h3><p>Nghiên cứu chủ đề, viết nội dung affiliate hữu ích, tạo bản nháp và tránh nội dung trùng lặp.</p><div class="agent-meta"><span>AI Writer</span><span>Campaign-aware</span><span>Daily workflow</span></div><button :disabled="autopilotBusy" @click="runAutopilot">{{ autopilotBusy ? 'Đang viết nội dung…' : '▶ Chạy Trợ lý nội dung' }}</button><p v-if="autopilotMessage" class="agent-message">{{ autopilotMessage }}</p></div></article>
      </div>
    </section>
    <section class="panel"><h2>Create a campaign</h2><p class="muted">Start with one niche and validate demand before scaling.</p><form @submit.prevent="createCampaign"><input v-model="name" placeholder="Campaign name" required minlength="2"><select v-model="niche"><option value="technology">Technology</option><option value="home">Home & living</option><option value="fashion">Fashion</option><option value="software">Software / SaaS</option><option value="other">Other</option></select><button :disabled="busy">{{ busy ? 'Đang tạo…' : 'Create campaign' }}</button></form><p v-if="error" class="error">{{ error }}</p></section>
    <section class="panel"><div class="panel-head"><h2>Campaign pipeline</h2><span class="muted">{{ campaigns.length }} total</span></div><div v-if="!campaigns.length" class="empty">No campaigns yet. Create the first campaign above.</div><div v-for="c in campaigns" :key="c.id" class="campaign"><div><b>{{ c.name }}</b><small>{{ c.niche }} · {{ c.network }}</small></div><span class="tag">{{ c.status }}</span></div></section>
    <section class="panel"><div class="panel-head"><div><h2>Khởi tạo chiến dịch SaaS</h2><p class="muted">Tải danh sách chương trình tiếp thị liên kết ban đầu kèm điều khoản hoa hồng từ trang chính thức.</p></div><button :disabled="seedBusy" @click="loadSaaSStarter">{{ seedBusy ? "Đang tải…" : "Tải danh sách SaaS mẫu" }}</button></div><p v-if="seedMessage" class="muted">{{ seedMessage }}</p></section>
    <section class="panel"><h2>Trợ lý nghiên cứu AI · Thêm cơ hội tiếp thị</h2><p class="muted">Thêm chương trình tiếp thị dựa trên thông tin đã kiểm chứng từ trang chính thức. Điểm số chỉ thể hiện mức ưu tiên nghiên cứu, không phải dự báo doanh thu.</p><form @submit.prevent="addOpportunity"><input v-model="productName" placeholder="Tên sản phẩm / SaaS" required minlength="2"><input v-model="vendor" placeholder="Tên nhà cung cấp"><input v-model.number="commission" type="number" min="0" max="100" step="0.5" aria-label="Commission percent"><label class="check"><input v-model="recurring" type="checkbox"> Hoa hồng định kỳ</label><button :disabled="researchBusy">{{ researchBusy ? 'Đang lưu…' : 'Đánh giá cơ hội' }}</button></form><p v-if="researchError" class="error">{{ researchError }}</p><div v-for="o in opportunities" :key="o.id" class="campaign"><div><b>{{ o.product_name }}</b><small>{{ o.vendor_name || 'Chưa có nhà cung cấp' }} · {{ o.network }} · {{ o.commission_pct }}% {{ o.recurring ? 'recurring' : 'một lần' }}</small><small v-if="o.ai_brief" class="brief">{{ o.ai_brief }}</small></div><div class="score"><b>{{ o.score }}/100</b><small>{{ o.recommendation.replaceAll('_',' ') }}</small><button class="mini" @click="analyzeOpportunity(o.id)">Phân tích</button></div></div><div v-if="!opportunities.length" class="empty">Chưa có cơ hội nào. Hãy thêm sản phẩm hoặc chương trình SaaS để bắt đầu.</div></section>
    <section class="panel"><div class="panel-head"><div><h2>systeme.io · Liên kết tiếp thị liên kết của bạn</h2><p class="muted">60% lifetime commission is the advertised program rate; actual earnings depend on eligible referrals and program terms.</p></div><button :disabled="draftBusy" @click="createSystemeDraft">{{ draftBusy ? 'Đang tạo…' : 'Tạo bản nháp đầu tiên' }}</button></div><div class="affiliate-link"><code>{{ systemeAffiliateLink }}</code><button class="mini" @click="globalThis.navigator?.clipboard?.writeText(systemeAffiliateLink)">Sao chép liên kết</button></div><p v-if="draftMessage" class="muted">{{ draftMessage }}</p><p class="muted">Bản nháp có thông báo liên kết tiếp thị. Nội dung được lưu để bạn duyệt, không tự động đăng.</p></section>
<section class="workspace-grid">
    <section class="panel content-panel"><div class="panel-head"><div><h2>Thư viện nội dung</h2><p class="muted">Quản lý bài viết viết, hình ảnh và kiểm duyệt trước khi đăng.</p></div><button class="mini" @click="loadDrafts">Làm mới</button></div><div class="content-tools"><input v-model="draftSearch" placeholder="Tìm kiếm nội dung..." aria-label="Tìm nội dung"><select v-model="draftStatusFilter" aria-label="Lọc trạng thái"><option value="all">Mọi trạng thái</option><option value="draft">Bản nháp</option></select><span class="muted">{{ filteredDrafts.length }} bài viết</span></div><div v-if="!filteredDrafts.length" class="empty">Chưa có bản nháp. Hãy chạy trợ lý nội dung hoặc làm mới danh sách.</div><div v-if="selectedDraft" class="selected-draft panel"><b>Đang chọn: {{ selectedDraft.title }}</b><p class="draft-body">{{ selectedDraft.body }}</p><div v-if="selectedDraft.image_url" class="draft-image"><img :src="selectedDraft.image_url" alt="Ảnh xem trước bài viết đăng"></div><p class="muted">Chọn ảnh trong thư viện bên cạnh rồi gắn vào bài viết đang chọn.</p><button class="mini" :disabled="!selectedMedia" @click="attachSelectedImage(selectedDraft)">Gắn ảnh đã chọn vào bài viết</button><p v-if="draftImageMessage" class="muted">{{ draftImageMessage }}</p></div><article v-for="d in filteredDrafts" :key="d.id" class="draft-card"><div class="panel-head"><b>{{ d.title }}</b><span class="tag">{{ d.status }}</span></div><button class="mini" @click="selectedDraftId=d.id">{{ selectedDraftId === d.id ? 'Đang xem bài viết này' : 'Chọn / xem bài viết viết' }}</button><p class="draft-body">{{ d.body }}</p><div v-if="d.image_url" class="draft-image"><img :src="d.image_url" alt="AI generated post image"><a :href="d.image_url" target="_blank" rel="noopener">Mở ảnh ↗</a></div><button class="mini" :disabled="imageBusy === d.id" @click="generateDraftImage(d)">{{ imageBusy === d.id ? "Đang tạo ảnh…" : d.image_url ? "Tạo lại ảnh" : "Tạo ảnh bằng AI" }}</button><button class="mini publish-btn" :disabled="publishBusy === d.id" @click="scheduleDraft(d)">{{ publishBusy === d.id ? "Đang đăng…" : "Đăng ngay" }}</button></article></section>
    <section class="panel image-panel"><div class="panel-head"><div><h2>Thư viện hình ảnh · Cloudinary</h2><p class="muted">Ảnh do AI tạo và ảnh tải lên · có thể gắn vào từng bản nháp.</p></div><label class="upload-btn">{{ mediaBusy ? 'Đang tải lên…' : 'Tải ảnh lên' }}<input type="file" accept="image/jpeg,image/png,image/webp" :disabled="mediaBusy" @change="uploadMedia"></label></div><p v-if="mediaMessage" class="muted">{{ mediaMessage }}</p><div v-if="!media.length" class="empty">Chưa có hình ảnh nào. Hãy tải ảnh lên để tạo thư viện.</div><div class="media-grid"><article v-for="m in media" :key="m.id" class="media-card" :class="{ selected: selectedMediaId === m.id }"><button class="mini" @click="selectedMediaId=m.id">{{ selectedMediaId === m.id ? 'Đã chọn ảnh' : 'Chọn ảnh' }}</button><img :src="m.url" :alt="m.filename"><small>{{ m.filename || m.public_id }}</small><a :href="m.url" target="_blank" rel="noopener">Mở ảnh ↗</a></article></div></section>
    </section>
    <section class="panel"><div class="panel-head"><div><h2>Trợ lý tiếp thị tự động</h2><p class="muted">Mỗi lần chạy, tạo 3 bản nháp hữu ích, khác biệt. Nội dung trùng lặp sẽ được bỏ qua.</p></div><button :disabled="autopilotBusy" @click="runAutopilot">{{ autopilotBusy ? 'Đang chạy…' : '▶ Chạy trợ lý tạo nội dung' }}</button></div><p v-if="autopilotMessage" class="muted">{{ autopilotMessage }}</p><label class="check"><input v-model="autoGenerateImages" type="checkbox"> Tự tạo ảnh AI cho các bài viết mới (có thể phát sinh phí API)</label><p class="muted">Khi bật, mỗi bản nháp mới sẽ được tạo một ảnh và lưu lên Cloudinary. Không có lịch tự đăng; chỉ xuất bản khi bạn duyệt và bấm Đăng ngay trên từng bài viết.</p></section>
    <section class="panel"><div class="panel-head"><div><h2>Nhật ký hoạt động</h2><p class="muted">Lọc theo ngày và xem trạng thái của từng thao tác.</p></div><div class="activity-tools"><input v-model="activityDate" type="date" aria-label="Lọc ngày"><button class="mini" @click="loadActivity">Lọc / Làm mới</button><button class="mini ghost" @click="activityDate = ''; loadActivity()">Tất cả</button></div></div><div v-if="!activity.length" class="empty">Chưa có hoạt động nào được ghi nhận. Khi trợ lý thực hiện thao tác, lịch sử sẽ hiển thị tại đây.</div><div v-for="a in activity" :key="a.id" class="campaign"><div><b>{{ a.message }}</b><small>{{ new Date(a.created_at).toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' }) }} · {{ a.event_type }}</small></div><span class="tag">{{ a.status }}</span></div></section>
    <section class="panel"><h2>Danh sách mạng lưới tiếp thị liên kết</h2><div v-for="n in networks" :key="n.name" class="campaign"><div><b>{{ n.name }}</b><small>{{ n.best_for }} · {{ n.cost }}</small></div><a :href="n.url" target="_blank" rel="noopener">Trang chính thức ↗</a></div></section>
    <footer>Mọi nội dung phải được bạn duyệt trước khi đăng, liên hệ đối tác hoặc chi tiền. Không mặc định có doanh thu.</footer>
  </main>
</template>
<style>
