:10px;min-width:0}.media-card img{width:100%;aspect-ratio:1;object-fit:cover;border-radius:7px}.media-card small{display:block;overflow-wrap:anywhere;margin:8px 0}.empty{padding:28px;color:#8da5bd;text-align:center}.error{color:#ff9d9d}footer{font-size:12px;margin-top:28px}@media(max-width:850px){.schedule-grid{grid-template-columns:1fr 1fr}.schedule-toggle{grid-column:1/-1}.shell{grid-template-columns:1fr}.workspace-grid{grid-template-columns:1fr}.shell>header,.shell>.metrics,.shell>footer,.shell>.panel{grid-column:1/-1}}@media(max-width:650px){.schedule-grid{grid-template-columns:1fr}.schedule-toggle{grid-column:auto}.manual-publish,.schedule-top{align-items:flex-start;flex-direction:column}.metrics{grid-template-columns:1fr}header{align-items:flex-start;flex-direction:column}form{flex-direction:column}button{padding:13px}}

.office-floor{grid-column:1/-1;margin:8px 0 10px;padding:26px;border:1px solid #294965;border-radius:22px;background:radial-gradient(ellipse at 50% -20%,#214a67 0%,#101f34 55%,#0b1728 100%);box-shadow:0 24px 60px #02091699;position:relative;overflow:hidden}.floor-heading,.agents-heading{display:flex;justify-content:space-between;align-items:flex-end;gap:16px;margin-bottom:20px}.floor-heading h2,.agents-heading h2{font-size:24px;margin:4px 0}.office-live{font-size:10px;color:#68f0ce;border:1px solid #277f72;border-radius:20px;padding:8px 12px;white-space:nowrap}.room-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;perspective:1100px}.room-card{border:1px solid #35536f;border-radius:15px;overflow:hidden;background:linear-gradient(145deg,#1c3650,#102137);box-shadow:0 14px 25px #020b18aa;transform:rotateX(2deg);transition:transform .2s,box-shadow .2s}.room-card:hover{transform:translateY(-5px) rotateX(0);box-shadow:0 22px 35px #020b18}.room-scene{height:118px;position:relative;display:grid;place-items:center;overflow:hidden;background:linear-gradient(145deg,#234c67,#142b47 60%,#101c34);border-bottom:1px solid #45627b}.room-scene:before,.room-scene:after{content:'';position:absolute;bottom:0;width:42%;height:75%;background:linear-gradient(90deg,#294a63,#172d46);border:1px solid #47627a;transform:skewY(-12deg);opacity:.8}.room-scene:before{left:-8%;}.room-scene:after{right:-8%;transform:skewY(12deg)}.room-icon{z-index:2;font-size:42px;filter:drop-shadow(0 8px 8px #020817);transform:translateY(-7px)}.room-orb{position:absolute;width:100px;height:100px;border-radius:50%;background:#4ce4d233;filter:blur(18px)}.room-desk{position:absolute;z-index:2;bottom:13px;width:62%;height:7px;border-radius:9px;background:#6e91a9;box-shadow:0 8px 0 #203d56,0 12px 20px #020817}.room-copy{padding:14px}.room-copy small,.agent-info>small{font-size:9px;letter-spacing:.15em;color:#64dcca}.room-copy h3{font-size:16px;margin:7px 0}.room-copy p,.agent-info p{font-size:11px;line-height:1.55;color:#9bb1c8;min-height:34px}.room-copy b{font-size:10px;color:#d6e7f6}.agents-heading{margin:28px 0 14px}.agent-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.agent-card{display:flex;gap:16px;padding:19px;border:1px solid #31536e;border-radius:16px;background:linear-gradient(135deg,#152d43,#101e32);box-shadow:0 12px 28px #02081766}.agent-avatar{width:54px;height:54px;flex:none;border-radius:15px;display:grid;place-items:center;font-size:28px;color:#061a23;background:linear-gradient(145deg,#74f4d9,#249eaa);box-shadow:0 8px 20px #30c8bb33}.content-agent .agent-avatar{background:linear-gradient(145deg,#d8b6ff,#8263d9)}.agent-info{min-width:0;flex:1}.agent-info h3{font-size:18px;margin:5px 0}.agent-status{font-size:9px;color:#6cebd5;font-weight:500;margin-left:7px}.agent-meta{display:flex;flex-wrap:wrap;gap:6px;margin:10px 0 13px}.agent-meta span{font-size:9px;color:#a9c2d8;padding:5px 8px;border:1px solid #34516c;border-radius:20px;background:#0b1a2b}.agent-info button{padding:10px 14px;font-size:11px}.agent-message{margin:9px 0 0!important;min-height:0!important;color:#75e6d3!important}.room-creative .room-orb{background:#9d77ff33}.room-publish .room-orb{background:#40baff33}.room-data .room-orb{background:#ffbd6c33}@media(max-width:1050px){.room-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:650px){.office-floor{padding:17px}.room-grid,.agent-grid{grid-template-columns:1fr}.floor-heading,.agents-heading{align-items:flex-start;flex-direction:column}.agent-card{padding:14px}.room-scene{height:100px}}

.collab-panel{margin:0 0 18px;padding:18px;border:1px solid #42617c;border-radius:16px;background:linear-gradient(135deg,#142d43,#0d1c30);box-shadow:inset 0 1px #ffffff0b}.collab-head{display:flex;justify-content:space-between;gap:15px;align-items:flex-start}.collab-head small{font-size:9px;letter-spacing:.16em;color:#70e6d0}.collab-head h3{font-size:18px;margin:6px 0}.collab-head p{font-size:11px;color:#9bb1c8;margin:0}.collab-pulse{font-size:10px;color:#75e9d3;white-space:nowrap}.collab-controls{display:flex;gap:10px;margin:15px 0}.collab-controls input{flex:1;min-width:0;padding:11px 13px;border:1px solid #36536e;border-radius:9px;background:#0a192a;color:#e4f2ff}.collab-controls button{white-space:nowrap}.conversation-feed{display:grid;gap:10px;max-height:430px;overflow:auto;padding-right:4px}.conversation-message{display:flex;gap:10px;padding:13px;border:1px solid #35516b;border-radius:12px;background:#0b1c2d}.conversation-message.from-image{background:#201b37;border-color:#51447a}.conversation-avatar{font-size:20px}.conversation-message b{font-size:11px;color:#7ce5d2}.from-image b{color:#c4a8ff}.conversation-message p{white-space:pre-wrap;font-size:12px;line-height:1.65;color:#d1deea;margin:6px 0 0}.conversation-empty{font-size:11px;color:#819bb3;text-align:center;padding:15px}.collab-controls button:disabled{opacity:.55}@media(max-width:650px){.collab-controls{flex-direction:column}.collab-head{flex-direction:column}}
